<script setup lang="ts">
import { onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { api, type AppSettings, type StorageSummary } from "../api/client";
import AdminLayout from "../components/AdminLayout.vue";
import AppIcon from "../components/AppIcon.vue";
import AppFooter from "../components/AppFooter.vue";
import { useToast } from "../composables/useToast";
const router=useRouter(),{notify}=useToast();
const loading=ref(true),savingRetention=ref(false),cleaning=ref(false),clearingLogs=ref(false),clearingWorkflowHistory=ref(false),deletingPacFiles=ref(false),resetting=ref(false);
const settings=ref<AppSettings|null>(null),storage=ref<StorageSummary|null>(null),error=ref("");
const retention=ref(30);
const maintenanceBusy=()=>cleaning.value||clearingLogs.value||clearingWorkflowHistory.value||deletingPacFiles.value||resetting.value;
function fileDateLabel(value:string|null){return value?new Date(value).toLocaleString():"—";}
function formatBytes(bytes:number){if(!Number.isFinite(bytes)||bytes<=0)return"0 B";const units=["B","KB","MB","GB","TB"],i=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),4);return(bytes/1024**i).toFixed(i===0?0:1)+" "+units[i];}
async function load(){loading.value=true;error.value="";try{const session=await api.session();if(!session.loggedIn){await router.replace("/admin/login");return;}if(session.mustChangePassword){await router.replace("/admin/settings");return;}const [s,st]=await Promise.all([api.settings(),api.storage()]);settings.value=s;retention.value=s.logRetentionDays;storage.value=st;}catch(e){error.value=e instanceof Error?e.message:String(e);notify(error.value,"error");}finally{loading.value=false;}}
async function saveRetention(){if(!settings.value||savingRetention.value)return;savingRetention.value=true;try{const saved=await api.saveSettings({...settings.value,logRetentionDays:retention.value});settings.value=saved;retention.value=saved.logRetentionDays;notify("日志保留时间保存成功","success");await refreshStorage();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{savingRetention.value=false;}}
async function refreshStorage(){try{storage.value=await api.storage();}catch(e){notify("刷新存储占用失败："+(e instanceof Error?e.message:String(e)),"error");}}
async function cleanupLogs(){if(maintenanceBusy())return;cleaning.value=true;try{const r=await api.cleanupLogs();notify(`日志清理完成：生成日志 ${r.deleted.generationLogs} 条、访问记录 ${r.deleted.accessEvents} 条、代理测试记录 ${r.deleted.proxyProbeRuns} 条。`,"success");await refreshStorage();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{cleaning.value=false;}}
async function clearAllLogs(){if(maintenanceBusy())return;if(!window.confirm("确定清空所有运行日志吗？这将立即删除全部生成日志、访问记录和代理测试记录，且无法撤销。工作流执行历史、应用配置和 PAC 文件不会被删除。"))return;clearingLogs.value=true;try{const r=await api.clearLogs();notify(`日志已清空：生成日志 ${r.deleted.generationLogs} 条、访问记录 ${r.deleted.accessEvents} 条、代理测试记录 ${r.deleted.proxyProbeRuns} 条。工作流历史已保留。`,"success");await refreshStorage();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{clearingLogs.value=false;}}
async function clearWorkflowHistory(){if(maintenanceBusy())return;if(!window.confirm("确定清空所有工作流执行历史吗？已完成、失败和已取消任务的记录及阶段详情都会被删除，且无法撤销。若仍有等待或执行中的任务，系统会拒绝清理。"))return;clearingWorkflowHistory.value=true;try{const r=await api.clearWorkflowHistory();notify(`已删除 ${r.deletedRuns} 条工作流执行历史及其阶段详情。`,"success");await refreshStorage();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{clearingWorkflowHistory.value=false;}}
async function deletePacFiles(){if(maintenanceBusy())return;if(!storage.value)return;if(!window.confirm("确定删除 PAC 文件吗？此操作会删除 proxy.pac 和 proxy.source.pac（如存在），不会删除规则配置或工作流历史；之后需要重新生成才能恢复文件。"))return;deletingPacFiles.value=true;try{const r=await api.deletePacFiles();if(r.deleted.length)notify("已删除 PAC 文件："+r.deleted.join("、")+"。","success");else notify("当前没有可删除的 PAC 文件。","info");await refreshStorage();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{deletingPacFiles.value=false;}}
async function factoryReset(){if(maintenanceBusy())return;if(!window.confirm("确定恢复出厂设置吗？这将重置应用配置、删除 PAC 文件和所有日志/工作流历史，且无法撤销。当前管理员密码会保留。"))return;resetting.value=true;try{const r=await api.factoryReset();notify(r.message,"success");await load();}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{resetting.value=false;}}
onMounted(()=>void load());
</script>
<template>
<AdminLayout active="system-settings" title="系统设置" subtitle="管理运行数据、日志保留策略与不可逆的系统维护操作。">
<div class="system-settings">
<section class="settings-panel"><div class="heading"><span class="icon-badge"><AppIcon name="database" :size="19"/></span><div><h2>存储占用</h2><p>查看数据库、日志和应用数据目录的当前占用。</p></div><button class="secondary" type="button" :disabled="loading" @click="refreshStorage"><AppIcon name="refresh-cw" :size="14"/> 刷新</button></div>
<div v-if="loading" class="state">正在读取系统数据…</div><div v-else-if="error" class="state error" role="alert">{{error}} <button class="secondary" @click="load">重试</button></div>
<div v-else-if="storage" class="metrics"><div class="metric"><span>数据目录占用</span><strong>{{formatBytes(storage.dataBytes)}}</strong><small>数据库、PAC 文件及其他数据</small></div><div class="metric"><span>数据库文件</span><strong>{{formatBytes(storage.dbBytes)}}</strong><small>包含 SQLite 主文件及 WAL 文件</small></div><div class="metric"><span>日志估算占用</span><strong>{{formatBytes(storage.logBytes)}}</strong><small>生成日志、访问记录与代理测试记录</small></div></div>
<div v-if="storage" class="counts"><span>生成日志 {{storage.counts.generationLogs}} 条</span><span>访问记录 {{storage.counts.accessEvents}} 条</span><span>代理测试 {{storage.counts.proxyProbeRuns}} 条</span><span>工作流历史 {{storage.counts.workflows}} 条</span></div></section>
<section class="settings-panel"><div class="heading"><span class="icon-badge"><AppIcon name="calendar-clock" :size="19"/></span><div><h2>日志保留策略</h2><p>自动清理超过指定期限的运行日志；工作流执行历史不受此项影响。</p></div></div><div class="retention"><label for="retention">自动清理期限</label><select id="retention" v-model.number="retention" :disabled="loading||savingRetention"><option :value="0">不自动清理</option><option :value="7">7 天</option><option :value="30">30 天</option><option :value="90">90 天</option><option :value="180">180 天</option><option :value="365">365 天</option></select><button class="primary" :disabled="loading||savingRetention||!settings||retention===settings.logRetentionDays" @click="saveRetention"><AppIcon :name="savingRetention?'loader-circle':'save'" :size="15"/> {{savingRetention?"保存中…":"保存保留策略"}}</button></div><p class="hint">策略保存后会用于服务启动时及运行期间的定期清理。</p></section>
<section class="settings-panel"><div class="heading"><span class="icon-badge"><AppIcon name="file-text" :size="19"/></span><div><h2>PAC 文件</h2><p>proxy.pac 是客户端使用的主文件，proxy.source.pac 是供状态页解析的辅助源文件。删除操作会同时清理两者，不会改动规则配置。</p></div><button class="secondary" type="button" :disabled="loading" @click="refreshStorage"><AppIcon name="refresh-cw" :size="14"/> 刷新状态</button></div><div v-if="storage" class="pac-files"><div class="pac-file"><div class="pac-file-head"><strong>proxy.pac</strong><span class="file-state" :class="storage.pacFiles.proxyPac.exists?'file-exists':'file-missing'">{{storage.pacFiles.proxyPac.exists?"已存在":"不存在"}}</span></div><p>客户端实际获取的 PAC 文件</p><div class="pac-file-meta"><span>大小：{{formatBytes(storage.pacFiles.proxyPac.sizeBytes)}}</span><span>修改时间：{{fileDateLabel(storage.pacFiles.proxyPac.modifiedAt)}}</span></div></div><div class="pac-file"><div class="pac-file-head"><strong>proxy.source.pac</strong><span class="file-state" :class="storage.pacFiles.proxySourcePac.exists?'file-exists':'file-missing'">{{storage.pacFiles.proxySourcePac.exists?"已存在":"不存在"}}</span></div><p>规则状态解析使用的未压缩源文件</p><div class="pac-file-meta"><span>大小：{{formatBytes(storage.pacFiles.proxySourcePac.sizeBytes)}}</span><span>修改时间：{{fileDateLabel(storage.pacFiles.proxySourcePac.modifiedAt)}}</span></div></div></div><p v-if="storage&&!storage.pacFiles.proxyPac.exists&&!storage.pacFiles.proxySourcePac.exists" class="empty-note">当前没有任何 PAC 文件。公共状态页会显示“还没有生成 PAC”，并提示前往配置管理生成文件。</p><button class="danger" type="button" :disabled="loading||maintenanceBusy()||!storage||(!storage.pacFiles.proxyPac.exists&&!storage.pacFiles.proxySourcePac.exists)" @click="deletePacFiles"><AppIcon :name="deletingPacFiles?'loader-circle':'trash-2'" :size="15"/> {{deletingPacFiles?"正在删除…":"删除 PAC 文件"}}</button><p class="hint">若有工作流正在等待或执行，服务器会拒绝删除，防止正在生成的文件被误删。</p></section><section class="settings-panel"><div class="heading"><span class="icon-badge"><AppIcon name="trash-2" :size="19"/></span><div><h2>日志清理</h2><p>可按当前保留期限清理过期日志，或立即清空全部运行日志。两种操作均不会删除工作流执行历史。</p></div></div><div class="maintenance-actions"><button class="secondary" :disabled="loading||maintenanceBusy()" @click="cleanupLogs"><AppIcon :name="cleaning ? 'loader-circle' : 'trash-2'" :size="15"/> {{cleaning ? "正在清理…" : "清理过期日志"}}</button><button class="danger" :disabled="loading||maintenanceBusy()" @click="clearAllLogs"><AppIcon :name="clearingLogs ? 'loader-circle' : 'trash-2'" :size="15"/> {{clearingLogs ? "正在清空…" : "清空所有日志"}}</button></div><p class="hint">“清理过期日志”遵循上方保留期限；“清空所有日志”会删除三类运行日志并整理数据库空间，操作前会要求确认。</p></section>
<section class="settings-panel"><div class="heading"><span class="icon-badge"><AppIcon name="workflow" :size="19"/></span><div><h2>工作流执行历史</h2><p>清除历史列表及其阶段详情；不会删除生成日志、应用配置或 PAC 文件。</p></div><span class="history-count">{{storage?storage.counts.workflows:0}} 条</span></div><button class="danger" type="button" :disabled="loading||maintenanceBusy()||!storage||storage.counts.workflows===0" @click="clearWorkflowHistory"><AppIcon :name="clearingWorkflowHistory?'loader-circle':'trash-2'" :size="15"/> {{clearingWorkflowHistory?"正在清理…":"清空工作流历史"}}</button><p class="hint">为避免破坏任务状态，只能在没有等待或执行中工作流时清空；删除不可撤销。</p></section><section class="settings-panel danger-panel"><div class="heading"><span class="icon-badge danger-icon"><AppIcon name="alert-triangle" :size="19"/></span><div><h2>恢复出厂设置</h2><p>重置 PAC 配置并删除已生成的 PAC 文件及日志、工作流历史。管理员密码会保留。</p></div></div><button class="danger" :disabled="loading||maintenanceBusy()" @click="factoryReset"><AppIcon :name="resetting?'loader-circle':'rotate-ccw'" :size="15"/> {{resetting?"正在恢复…":"恢复出厂设置"}}</button><p class="hint">此操作不可撤销，请确认已备份需要保留的数据。</p></section>
<AppFooter/></div>
</AdminLayout>
</template>
<style scoped>
.system-settings{display:grid;gap:18px}.settings-panel{min-width:0;padding:22px;border:1px solid var(--line);border-radius:13px;background:var(--surface);box-shadow:var(--shadow-sm,0 4px 18px #00000008)}.heading{display:flex;align-items:center;gap:12px;margin-bottom:18px}.heading>div{flex:1;min-width:0}.heading h2{margin:0;color:var(--text);font-size:16px}.heading p{margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.55}.icon-badge{display:grid;place-items:center;flex:0 0 40px;width:40px;height:40px;border:1px solid var(--line);border-radius:11px;color:var(--accent);background:var(--surface-2)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.metric{display:grid;gap:7px;padding:15px;border:1px solid var(--line);border-radius:10px;background:var(--surface-2);min-width:0}.metric span,.metric small{color:var(--muted);font-size:11px}.metric strong{font-size:22px;color:var(--text);overflow-wrap:anywhere}.counts{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:14px;color:var(--muted);font-size:11px}.pac-files{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:14px}.pac-file{display:grid;gap:8px;min-width:0;padding:14px;border:1px solid var(--line);border-radius:10px;background:var(--surface-2)}.pac-file-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.pac-file-head strong{font-size:13px;overflow-wrap:anywhere}.pac-file p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.pac-file-meta{display:grid;gap:5px;color:var(--muted);font-size:11px;overflow-wrap:anywhere}.file-state{padding:3px 7px;border:1px solid var(--line);border-radius:999px;font-size:10px;font-weight:700;white-space:nowrap}.file-exists{color:var(--green);border-color:color-mix(in srgb,var(--green) 35%,var(--line))}.file-missing{color:var(--muted)}.empty-note{margin:0 0 14px;padding:12px;border:1px dashed var(--line);border-radius:9px;color:var(--muted);font-size:12px;line-height:1.6}.history-count{flex:0 0 auto;padding:4px 9px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:11px}.maintenance-actions{display:flex;flex-wrap:wrap;gap:10px}.retention{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.retention label{font-size:12px;font-weight:700;color:var(--text)}select{min-height:38px;padding:0 12px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);font:inherit;font-size:12px}.primary,.secondary,.danger{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:12px;font-weight:700;cursor:pointer}.primary{background:var(--accent);border-color:var(--accent);color:white}.secondary{background:var(--surface);color:var(--text)}.danger{background:var(--red-soft);border-color:color-mix(in srgb,var(--red) 35%,var(--line));color:var(--red)}button:disabled{opacity:.55;cursor:not-allowed}.hint{margin:10px 0 0;color:var(--muted);font-size:11px;line-height:1.6}.danger-panel{border-color:color-mix(in srgb,var(--red) 24%,var(--line))}.danger-icon{color:var(--red)}.state{padding:14px 0;color:var(--muted);font-size:13px}.state.error{color:var(--red)}@media(max-width:650px){.settings-panel{padding:15px}.metrics{grid-template-columns:1fr}.pac-files{grid-template-columns:1fr}.metric strong{font-size:20px}.heading{align-items:flex-start}.retention{align-items:stretch;flex-direction:column}.retention>*{width:100%}}
</style>